// Package template implements the YAML-based profile engine for Hub Lab.
// Profiles define how to parse, extract, and map data from autoanalyzer messages.
package template

import (
	"fmt"
	"os"
	"strings"

	"gopkg.in/yaml.v3"
)

// Profile represents a complete analyzer profile (canonical).
type Profile struct {
	Analyzer    AnalyzerDef       `yaml:"analyzer" json:"analyzer"`
	Connection  ConnectionDef     `yaml:"connection" json:"connection"`
	Message     MessageDef        `yaml:"message" json:"message"`
	Extraction  ExtractionDef     `yaml:"extraction" json:"extraction"`
	Mapping     MappingDef        `yaml:"mapping" json:"mapping"`
	Validation  *ValidationConfig `yaml:"validation,omitempty" json:"validation,omitempty"`
	Output      OutputDef         `yaml:"output,omitempty" json:"output,omitempty"`
	Overrides   *OverrideDef      `yaml:"overrides,omitempty" json:"overrides,omitempty"`
}

// AnalyzerDef identifies the analyzer model.
type AnalyzerDef struct {
	Model        string `yaml:"model" json:"model"`
	Manufacturer string `yaml:"manufacturer" json:"manufacturer"`
	Protocol     string `yaml:"protocol" json:"protocol"` // ASTM_E1394, HL7_2x, CSV, etc.
}

// ConnectionDef defines how to connect to the analyzer.
type ConnectionDef struct {
	Type    string `yaml:"type" json:"type"`    // tcp_server, tcp_client, serial, file_watcher
	Port    int    `yaml:"port,omitempty" json:"port,omitempty"`
	Host    string `yaml:"host,omitempty" json:"host,omitempty"`
	Framing string `yaml:"framing,omitempty" json:"framing,omitempty"` // MLLP, raw, crlf
	TLS     bool   `yaml:"tls,omitempty" json:"tls,omitempty"`
}

// MessageDef defines the message structure.
type MessageDef struct {
	Type      string           `yaml:"type" json:"type"` // ASTM, HL7, CSV, JSON
	Structure *StructureDef    `yaml:"structure,omitempty" json:"structure,omitempty"`
	Options   map[string]string `yaml:"options,omitempty" json:"options,omitempty"`
}

// StructureDef defines message templates for each segment type.
type StructureDef struct {
	Header     string `yaml:"header,omitempty" json:"header,omitempty"`
	Patient    string `yaml:"patient,omitempty" json:"patient,omitempty"`
	Order      string `yaml:"order,omitempty" json:"order,omitempty"`
	Result     string `yaml:"result,omitempty" json:"result,omitempty"`
	Comment    string `yaml:"comment,omitempty" json:"comment,omitempty"`
	Terminator string `yaml:"terminator,omitempty" json:"terminator,omitempty"`
}

// ExtractionDef defines how to extract fields from parsed messages.
type ExtractionDef struct {
	// Simple string fields
	SampleID    string `yaml:"sampleId,omitempty" json:"sampleId,omitempty"`
	TestCode    string `yaml:"testCode,omitempty" json:"testCode,omitempty"`
	Value       string `yaml:"value,omitempty" json:"value,omitempty"`
	Unit        string `yaml:"unit,omitempty" json:"unit,omitempty"`
	AbnormalFlag string `yaml:"abnormalFlag,omitempty" json:"abnormalFlag,omitempty"`
	ResultStatus string `yaml:"resultStatus,omitempty" json:"resultStatus,omitempty"`
	DateTime    string `yaml:"dateTime,omitempty" json:"dateTime,omitempty"`
	InstrumentID string `yaml:"instrumentId,omitempty" json:"instrumentId,omitempty"`
	// Additional custom fields
	Extra map[string]string `yaml:"extra,omitempty" json:"extra,omitempty"`
}

// MappingDef defines how to map extracted test codes to LOINC/UCUM.
type MappingDef struct {
	TestCodes            map[string]TestCodeMapping `yaml:"test_codes" json:"test_codes"`
	DefaultUnitConversion *UnitConversion           `yaml:"default_unit_conversion,omitempty" json:"default_unit_conversion,omitempty"`
	ExtraTests           map[string]TestCodeMapping `yaml:"extra_tests,omitempty" json:"extra_tests,omitempty"`
}

// TestCodeMapping maps an analyzer-specific test code to LOINC.
type TestCodeMapping struct {
	LOINC      string `yaml:"loinc" json:"loinc"`
	LongName   string `yaml:"long_name" json:"long_name"`
	UCUM       string `yaml:"ucum" json:"ucum"`
	Conversion string `yaml:"conversion,omitempty" json:"conversion,omitempty"` // formula or "value" for identity
}

// UnitConversion defines a unit conversion rule.
type UnitConversion struct {
	SourceUnit string  `yaml:"source_unit" json:"source_unit"`
	TargetUnit string  `yaml:"target_unit" json:"target_unit"`
	Factor     float64 `yaml:"factor" json:"factor"`
}

// --- Validation types (used by validation engine) ---

// ValidationAction defines what happens when a validation rule matches.
type ValidationAction string

