1	// Package pipeline implements the message processing pipeline:
2	// parser → transformer → outbound workers connected via EventBus.
3	package pipeline
4	
5	import (
6		"context"
7		"encoding/json"
8		"fmt"
9		"log"
10		"time"
11	
12		"github.com/hub-lab/backend/internal/core/domain"
13		"github.com/hub-lab/backend/internal/core/engine/mapping"
14		"github.com/hub-lab/backend/internal/core/engine/template"
15		"github.com/hub-lab/backend/internal/core/engine/validation"
16		"github.com/hub-lab/backend/internal/core/outbound"
17		"github.com/hub-lab/backend/internal/core/parser/astm"
18		hl7parser "github.com/hub-lab/backend/internal/core/parser/hl7"
19		"github.com/hub-lab/backend/internal/core/result"
20		"github.com/hub-lab/backend/pkg/canonical"
21		"github.com/hub-lab/backend/pkg/eventbus"
22	)
23	
24	// ParserWorker consumes raw messages and produces parsed messages.
25	type ParserWorker struct {
26		bus      eventbus.Bus
27		profiles *template.Loader
28	}
29	
30	// NewParserWorker creates a new parser worker.
31	func NewParserWorker(bus eventbus.Bus, profiles *template.Loader) *ParserWorker {
32		return &ParserWorker{bus: bus, profiles: profiles}
33	}
34	
35	// Start subscribes to raw messages and starts parsing.
36	func (w *ParserWorker) Start() error {
37		return w.bus.Subscribe("ingest.raw", w.handleRawMessage)
38	}
39	
40	func (w *ParserWorker) handleRawMessage(ctx context.Context, msg eventbus.Message) error {
41		var raw domain.RawMessage
42		if err := json.Unmarshal(msg.Payload, &raw); err != nil {
43			log.Printf("[Parser] Failed to unmarshal raw message: %v", err)
44			return err
45		}
46	
47		// Validate by attempting to parse (but store raw data for pipeline)
48		switch raw.Protocol {
49		case domain.ProtoASTM:
50			if _, err := astm.Parse(raw.Data); err != nil {
51				log.Printf("[Parser] ASTM parse error: %v", err)
52				return err
53			}
54		case domain.ProtoHL7:
55			if _, err := hl7parser.Parse(raw.Data); err != nil {
56				log.Printf("[Parser] HL7 parse error: %v", err)
57				return err
58			}
59		}
60	
61		parsed := domain.ParsedMessage{
62			RawMessageID:  raw.ID,
63			Protocol:      raw.Protocol,
64			CorrelationID: raw.ID,
65			ParsedAt:      time.Now(),
66			RawData:       raw.Data,
67		}
68	
69		return w.bus.Publish(ctx, "pipeline.parsed", parsed)
70	}
71	
72	// TransformWorker consumes parsed messages and produces canonical results.
73	type TransformWorker struct {
74		bus      eventbus.Bus
75		profiles *template.Loader
76	}
77	
78	// NewTransformWorker creates a new transform worker.
79	func NewTransformWorker(bus eventbus.Bus, profiles *template.Loader) *TransformWorker {
80		return &TransformWorker{bus: bus, profiles: profiles}
81	}
82	
83	// Start subscribes to parsed messages and starts transforming.
84	func (w *TransformWorker) Start() error {
85		return w.bus.Subscribe("pipeline.parsed", w.handleParsedMessage)
86	}
87	
88	func (w *TransformWorker) handleParsedMessage(ctx context.Context, msg eventbus.Message) error {
89		var parsed domain.ParsedMessage
90		if err := json.Unmarshal(msg.Payload, &parsed); err != nil {
91			log.Printf("[Transform] Failed to unmarshal: %v", err)
92			return err
93		}
94	
95		// Find appropriate profile
96		p := w.profiles.First()
97		if p == nil {
98			log.Printf("[Transform] No profile available")
99			return nil
100		}
101	
102		extractor := template.NewExtractor(p)
103		mapper := mapping.NewMapper(p)
104	
105		var results []*template.ExtractedData
106		var sampleID string
107	
108		switch parsed.Protocol {
109		case domain.ProtoASTM:
110			astmMsg, err := astm.Parse(parsed.RawData)
111			if err != nil {
112				log.Printf("[Transform] ASTM re-parse error: %v", err)
113				return err
114			}
115			results, err = extractor.ExtractAllResultsFromASTM(astmMsg)
116			if err != nil {
117				log.Printf("[Transform] ASTM extraction error: %v", err)
118				return err
119			}
120			if data, err := extractor.ExtractFromASTM(astmMsg); err == nil {
121				sampleID = data.SampleID
122			}
123	
124		case domain.ProtoHL7:
125			hl7Msg, err := hl7parser.Parse(parsed.RawData)
126			if err != nil {
127				log.Printf("[Transform] HL7 re-parse error: %v", err)
128				return err
129			}
130			results, err = extractor.ExtractAllResultsFromHL7(hl7Msg)
131			if err != nil {
132				log.Printf("[Transform] HL7 extraction error: %v", err)
133				return err
134			}
135			if data, err := extractor.ExtractFromHL7(hl7Msg); err == nil {
136				sampleID = data.SampleID
137			}
138		}
139	
140		if len(results) == 0 {
141			log.Printf("[Transform] No results extracted")
142			return nil
143		}
144	
145		// Map to canonical FHIR report
146		report, err := mapper.MapToReport(results, sampleID)
147		if err != nil {
148			log.Printf("[Transform] Mapping error: %v", err)
149			return err
150		}
151	
152		// Validate results
153		validator := validation.NewService(p.Validation)
154		vResult := validator.ValidateBatch(results)
155	
156		result := domain.CanonicalResult{
157			CorrelationID: parsed.CorrelationID,
158			SampleID:      sampleID,
159			Observations:  report,
160			MappedAt:      time.Now(),
161		}
162	
163		if vResult.Status == validation.StatusHeld {
164			log.Printf("[Transform] Result held for review: %s - %s", sampleID, vResult.Message)
165			return w.bus.Publish(ctx, "pipeline.held", result)
166		}
167	
168		if vResult.Status == validation.StatusRejected {
169			log.Printf("[Transform] Result rejected: %s - %s", sampleID, vResult.Message)
170			return w.bus.Publish(ctx, "pipeline.rejected", result)
171		}
172	
173		return w.bus.Publish(ctx, "pipeline.canonical", result)
174	}
175	
176	// OutboundWorkerConfig holds configuration for outbound delivery.
177	type OutboundWorkerConfig struct {
178		// DefaultLISHost is the fallback LIS host for delivery.
179		DefaultLISHost string `json:"default_lis_host"`
180		// DefaultLISPort is the fallback LIS port (usually 7777 for emulator, 2575 in production).
181		DefaultLISPort int `json:"default_lis_port"`
182	}
183	
184	// OutboundWorker consumes canonical results and delivers to LIS.
185	type OutboundWorker struct {
186		bus         eventbus.Bus
187		cfg         OutboundWorkerConfig
188		resultStore result.Store
189	}
190	
191	// NewOutboundWorker creates a new outbound worker.
192	func NewOutboundWorker(bus eventbus.Bus) *OutboundWorker {
193		return &OutboundWorker{
194			bus: bus,
195			cfg: OutboundWorkerConfig{
196				DefaultLISHost: "localhost",
197				DefaultLISPort: 7777,
198			},
199		}
200	}
201	
202	// NewOutboundWorkerWithConfig creates an outbound worker with config and result store.
203	func NewOutboundWorkerWithConfig(bus eventbus.Bus, cfg OutboundWorkerConfig, rs result.Store) *OutboundWorker {
204		if cfg.DefaultLISHost == "" {
205			cfg.DefaultLISHost = "localhost"
206		}
207		if cfg.DefaultLISPort == 0 {
208			cfg.DefaultLISPort = 7777
209		}
210		return &OutboundWorker{
211			bus:         bus,
212			cfg:         cfg,
213			resultStore: rs,
214		}
215	}
216	
217	// Start subscribes to canonical and approved results.
218	func (w *OutboundWorker) Start() error {
219		_ = w.bus.Subscribe("pipeline.canonical", w.handleCanonicalResult)
220		_ = w.bus.Subscribe("pipeline.approved", w.handleCanonicalResult) // approved from review queue
221		return nil
222	}
223	
224	func (w *OutboundWorker) handleCanonicalResult(ctx context.Context, msg eventbus.Message) error {
225		var result domain.CanonicalResult
226		if err := json.Unmarshal(msg.Payload, &result); err != nil {
227			// Try to unmarshal as the event wrapper from result handlers
228			var eventWrapper struct {
229				ResultID string `json:"result_id"`
230				Action   string `json:"action"`
231			}
232			if err2 := json.Unmarshal(msg.Payload, &eventWrapper); err2 == nil && eventWrapper.Action == "approved" {
233				log.Printf("[Outbound] Received approved event, will deliver via normal flow")
234				return nil
235			}
236			log.Printf("[Outbound] Failed to unmarshal: %v", err)
237			return err
238		}
239	
240		log.Printf("[Outbound] Result ready for delivery - Sample: %s, Correlation: %s",
241			result.SampleID, result.CorrelationID)
242	
243		// Persist results to DB if store is available
244		if w.resultStore != nil {
245			w.persistResults(&result)
246		}
247	
248		// Deliver to LIS via MLLP
249		delivery := w.deliverToLIS(ctx, &result)
250	
251		return w.bus.Publish(ctx, "pipeline.delivered", delivery)
252	}
253	
254	// persistResults extracts observations from the canonical result and stores them.
255	func (w *OutboundWorker) persistResults(cr *domain.CanonicalResult) {
256		// Extract observations from the diagnostic report
257		report, ok := cr.Observations.(*canonical.DiagnosticReport)
258		if !ok {
259			// Try slice of observations
260			obsSlice, ok2 := cr.Observations.([]*canonical.Observation)
261			if !ok2 {
262				log.Printf("[Outbound] Unknown observation type, skipping persistence")
263				return
264			}
265			entries := make([]*result.ResultEntry, 0, len(obsSlice))
266			for _, obs := range obsSlice {
267				entry := w.observationToEntry(cr, obs)
268				entries = append(entries, entry)
269			}
270			if err := w.resultStore.CreateBatch(entries); err != nil {
271				log.Printf("[Outbound] Failed to persist results: %v", err)
272			}
273			return
274		}
275	
276		// We only have references in the report, not the full observations.
277		// For now, store a single entry representing the sample.
278		entry := &result.ResultEntry{
279			ID:             domain.NewCorrelationID(),
280			CorrelationID:  cr.CorrelationID,
281			SampleID:       cr.SampleID,
282			TestCode:       report.Code.Code,
283			TestName:       report.Code.Display,
284			Status:         result.StatusSent,
285		}
286		if err := w.resultStore.Create(entry); err != nil {
287			log.Printf("[Outbound] Failed to persist result: %v", err)
288		} else {
289			log.Printf("[Outbound] Persisted result for sample %s", cr.SampleID)
290		}
291	}
292	
293	// observationToEntry converts a canonical observation to a result entry.
294	func (w *OutboundWorker) observationToEntry(cr *domain.CanonicalResult, obs *canonical.Observation) *result.ResultEntry {
295		entry := &result.ResultEntry{
296			ID:            domain.NewCorrelationID(),
297			CorrelationID: cr.CorrelationID,
298			SampleID:      cr.SampleID,
299			TestCode:      obs.Code.Code,
300			TestName:      obs.Code.Display,
301			Unit:          "",
302			Flag:          "N",
303			Status:        result.StatusSent,
304			CreatedAt:     time.Now().UTC(),
305		}
306	
307		if obs.ValueQuantity != nil {
308			entry.Value = obs.ValueQuantity.Value
309			entry.Unit = obs.ValueQuantity.Unit
310		}
311	
312		// Extract interpretation flag
313		if len(obs.Interpretation) > 0 {
314			ic := obs.Interpretation[0]
315			entry.Flag = ic.Code
316			if entry.Flag == "H" || entry.Flag == "L" {
317				entry.HoldReason = fmt.Sprintf("Abnormal flag: %s", ic.Display)
318				entry.Status = result.StatusHeld
319			}
320		}
321	
322		return entry
323	}
324	
325	// deliverToLIS sends the result to the LIS via MLLP/HL7.
326	func (w *OutboundWorker) deliverToLIS(ctx context.Context, cr *domain.CanonicalResult) *domain.DeliveryStatus {
327		adapter := outbound.NewHL7Adapter(outbound.HL7Config{
328			Host:      w.cfg.DefaultLISHost,
329			Port:      w.cfg.DefaultLISPort,
330			TLS:       false,
331			Timeout:   10 * time.Second,
332			MaxRetries: 2,
333			RetryBackoff: 1 * time.Second,
334		})
335	
336		// If we have a diagnostic report, send it
337		report, ok := cr.Observations.(*canonical.DiagnosticReport)
338		if !ok {
339			// Try to build from result entries if we have a store
340			log.Printf("[Outbound] No diagnostic report available for delivery, skipping MLLP send")
341			return &domain.DeliveryStatus{
342				CorrelationID: cr.CorrelationID,
343				Success:       true,
344				DeliveredAt:   time.Now(),
345			}
346		}
347	
348		status, err := adapter.Send(ctx, report, cr.SampleID)
349	
350		// Update DB delivery status
351		if w.resultStore != nil && err == nil {
352			// Find all results for this correlation and mark as delivered
353			results, _ := w.resultStore.List(result.ResultFilter{SampleID: cr.SampleID})
354			for _, r := range results {
355				if r.Status == result.StatusSent || r.Status == result.StatusApproved {
356					ds := result.StatusDelivered
357					if !status.Success {
358						ds = result.StatusFailed
359					}
360					_ = w.resultStore.(*result.SQLiteStore).UpdateDeliveryStatus(r.ID, ds)
361				}
362			}
363		}
364	
365		if err != nil {
366			log.Printf("[Outbound] Delivery error for sample %s: %v", cr.SampleID, err)
367		} else {
368			log.Printf("[Outbound] Delivered to LIS (%s:%d) - Sample: %s, Success: %v",
369				w.cfg.DefaultLISHost, w.cfg.DefaultLISPort, cr.SampleID, status.Success)
370		}
371	
372		return status
373	}
