// Package pipeline implements the message processing pipeline:
// parser → transformer → outbound workers connected via EventBus.
package pipeline

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"time"

	"github.com/hub-lab/backend/internal/core/domain"
	"github.com/hub-lab/backend/internal/core/engine/mapping"
	"github.com/hub-lab/backend/internal/core/engine/template"
	"github.com/hub-lab/backend/internal/core/engine/validation"
	"github.com/hub-lab/backend/internal/core/outbound"
	"github.com/hub-lab/backend/internal/core/parser/astm"
	hl7parser "github.com/hub-lab/backend/internal/core/parser/hl7"
	"github.com/hub-lab/backend/internal/core/result"
	"github.com/hub-lab/backend/pkg/canonical"
	"github.com/hub-lab/backend/pkg/eventbus"
)

// ParserWorker consumes raw messages and produces parsed messages.
type ParserWorker struct {
	bus      eventbus.Bus
	profiles *template.Loader
}

// NewParserWorker creates a new parser worker.
func NewParserWorker(bus eventbus.Bus, profiles *template.Loader) *ParserWorker {
	return &ParserWorker{bus: bus, profiles: profiles}
}

// Start subscribes to raw messages and starts parsing.
func (w *ParserWorker) Start() error {
	return w.bus.Subscribe("ingest.raw", w.handleRawMessage)
}

func (w *ParserWorker) handleRawMessage(ctx context.Context, msg eventbus.Message) error {
	var raw domain.RawMessage
	if err := json.Unmarshal(msg.Payload, &raw); err != nil {
		log.Printf("[Parser] Failed to unmarshal raw message: %v", err)
		return err
	}

	// Validate by attempting to parse (but store raw data for pipeline)
	switch raw.Protocol {
	case domain.ProtoASTM:
		if _, err := astm.Parse(raw.Data); err != nil {
			log.Printf("[Parser] ASTM parse error: %v", err)
			return err
		}
	case domain.ProtoHL7:
		if _, err := hl7parser.Parse(raw.Data); err != nil {
			log.Printf("[Parser] HL7 parse error: %v", err)
			return err
		}
	}

	parsed := domain.ParsedMessage{
		RawMessageID:  raw.ID,
		Protocol:      raw.Protocol,
		CorrelationID: raw.ID,
		ParsedAt:      time.Now(),
		RawData:       raw.Data,
	}

	return w.bus.Publish(ctx, "pipeline.parsed", parsed)
}

// TransformWorker consumes parsed messages and produces canonical results.
type TransformWorker struct {
	bus      eventbus.Bus
	profiles *template.Loader
}

// NewTransformWorker creates a new transform worker.
func NewTransformWorker(bus eventbus.Bus, profiles *template.Loader) *TransformWorker {
	return &TransformWorker{bus: bus, profiles: profiles}
}

// Start subscribes to parsed messages and starts transforming.
func (w *TransformWorker) Start() error {
	return w.bus.Subscribe("pipeline.parsed", w.handleParsedMessage)
}

func (w *TransformWorker) handleParsedMessage(ctx context.Context, msg eventbus.Message) error {
	var parsed domain.ParsedMessage
	if err := json.Unmarshal(msg.Payload, &parsed); err != nil {
		log.Printf("[Transform] Failed to unmarshal: %v", err)
		return err
	}

	// Find appropriate profile
	p := w.profiles.First()
	if p == nil {
		log.Printf("[Transform] No profile available")
		return nil
	}

	extractor := template.NewExtractor(p)
	mapper := mapping.NewMapper(p)

	var results []*template.ExtractedData
	var sampleID string

	switch parsed.Protocol {
	case domain.ProtoASTM:
		astmMsg, err := astm.Parse(parsed.RawData)
		if err != nil {
			log.Printf("[Transform] ASTM re-parse error: %v", err)
			return err
		}
		results, err = extractor.ExtractAllResultsFromASTM(astmMsg)
		if err != nil {
			log.Printf("[Transform] ASTM extraction error: %v", err)
			return err
		}
		if data, err := extractor.ExtractFromASTM(astmMsg); err == nil {
			sampleID = data.SampleID
		}

	case domain.ProtoHL7:
		hl7Msg, err := hl7parser.Parse(parsed.RawData)
		if err != nil {
			log.Printf("[Transform] HL7 re-parse error: %v", err)
			return err
		}
		results, err = extractor.ExtractAllResultsFromHL7(hl7Msg)
		if err != nil {
			log.Printf("[Transform] HL7 extraction error: %v", err)
			return err
		}
		if data, err := extractor.ExtractFromHL7(hl7Msg); err == nil {
			sampleID = data.SampleID
		}
	}

	if len(results) == 0 {
		log.Printf("[Transform] No results extracted")
		return nil
	}

	// Map to canonical FHIR report
	report, err := mapper.MapToReport(results, sampleID)
	if err != nil {
		log.Printf("[Transform] Mapping error: %v", err)
		return err
	}

	// Validate results
	validator := validation.NewService(p.Validation)
	vResult := validator.ValidateBatch(results)

	result := domain.CanonicalResult{
		CorrelationID: parsed.CorrelationID,
		SampleID:      sampleID,
		Observations:  report,
		MappedAt:      time.Now(),
	}

	if vResult.Status == validation.StatusHeld {
		log.Printf("[Transform] Result held for review: %s - %s", sampleID, vResult.Message)
		return w.bus.Publish(ctx, "pipeline.held", result)
	}

	if vResult.Status == validation.StatusRejected {
		log.Printf("[Transform] Result rejected: %s - %s", sampleID, vResult.Message)
		return w.bus.Publish(ctx, "pipeline.rejected", result)
	}

	return w.bus.Publish(ctx, "pipeline.canonical", result)
}

// OutboundWorkerConfig holds configuration for outbound delivery.
type OutboundWorkerConfig struct {
	// DefaultLISHost is the fallback LIS host for delivery.
	DefaultLISHost string `json:"default_lis_host"`
	// DefaultLISPort is the fallback LIS port (usually 7777 for emulator, 2575 in production).
	DefaultLISPort int `json:"default_lis_port"`
}

// OutboundWorker consumes canonical results and delivers to LIS.
type OutboundWorker struct {
	bus         eventbus.Bus
	cfg         OutboundWorkerConfig
	resultStore result.Store
}

// NewOutboundWorker creates a new outbound worker.
func NewOutboundWorker(bus eventbus.Bus) *OutboundWorker {
	return &OutboundWorker{
		bus: bus,
		cfg: OutboundWorkerConfig{
			DefaultLISHost: "localhost",
			DefaultLISPort: 7777,
		},
	}
}

// NewOutboundWorkerWithConfig creates an outbound worker with config and result store.
func NewOutboundWorkerWithConfig(bus eventbus.Bus, cfg OutboundWorkerConfig, rs result.Store) *OutboundWorker {
	if cfg.DefaultLISHost == "" {
		cfg.DefaultLISHost = "localhost"
	}
	if cfg.DefaultLISPort == 0 {
		cfg.DefaultLISPort = 7777
	}
	return &OutboundWorker{
		bus:         bus,
		cfg:         cfg,
		resultStore: rs,
	}
}

// Start subscribes to canonical and approved results.
func (w *OutboundWorker) Start() error {
	_ = w.bus.Subscribe("pipeline.canonical", w.handleCanonicalResult)
	_ = w.bus.Subscribe("pipeline.approved", w.handleCanonicalResult) // approved from review queue
	return nil
}

func (w *OutboundWorker) handleCanonicalResult(ctx context.Context, msg eventbus.Message) error {
	var result domain.CanonicalResult
	if err := json.Unmarshal(msg.Payload, &result); err != nil {
		// Try to unmarshal as the event wrapper from result handlers
		var eventWrapper struct {
			ResultID string `json:"result_id"`
			Action   string `json:"action"`
		}
		if err2 := json.Unmarshal(msg.Payload, &eventWrapper); err2 == nil && eventWrapper.Action == "approved" {
			log.Printf("[Outbound] Received approved event, will deliver via normal flow")
			return nil
		}
		log.Printf("[Outbound] Failed to unmarshal: %v", err)
		return err
	}

	log.Printf("[Outbound] Result ready for delivery - Sample: %s, Correlation: %s",
		result.SampleID, result.CorrelationID)

	// Persist results to DB if store is available
	if w.resultStore != nil {
		w.persistResults(&result)
	}

	// Deliver to LIS via MLLP
	delivery := w.deliverToLIS(ctx, &result)

	return w.bus.Publish(ctx, "pipeline.delivered", delivery)
}

// persistResults extracts observations from the canonical result and stores them.
func (w *OutboundWorker) persistResults(cr *domain.CanonicalResult) {
	// Extract observations from the diagnostic report
	report, ok := cr.Observations.(*canonical.DiagnosticReport)
	if !ok {
		// Try slice of observations
		obsSlice, ok2 := cr.Observations.([]*canonical.Observation)
		if !ok2 {
			log.Printf("[Outbound] Unknown observation type, skipping persistence")
			return
		}
		entries := make([]*result.ResultEntry, 0, len(obsSlice))
		for _, obs := range obsSlice {
			entry := w.observationToEntry(cr, obs)
			entries = append(entries, entry)
		}
		if err := w.resultStore.CreateBatch(entries); err != nil {
			log.Printf("[Outbound] Failed to persist results: %v", err)
		}
		return
	}

	// We only have references in the report, not the full observations.
	// For now, store a single entry representing the sample.
	entry := &result.ResultEntry{
		ID:             domain.NewCorrelationID(),
		CorrelationID:  cr.CorrelationID,
		SampleID:       cr.SampleID,
		TestCode:       report.Code.Code,
		TestName:       report.Code.Display,
		Status:         result.StatusSent,
	}
	if err := w.resultStore.Create(entry); err != nil {
		log.Printf("[Outbound] Failed to persist result: %v", err)
	} else {
		log.Printf("[Outbound] Persisted result for sample %s", cr.SampleID)
	}
}

// observationToEntry converts a canonical observation to a result entry.
func (w *OutboundWorker) observationToEntry(cr *domain.CanonicalResult, obs *canonical.Observation) *result.ResultEntry {
	entry := &result.ResultEntry{
		ID:            domain.NewCorrelationID(),
		CorrelationID: cr.CorrelationID,
		SampleID:      cr.SampleID,
		TestCode:      obs.Code.Code,
		TestName:      obs.Code.Display,
		Unit:          "",
		Flag:          "N",
		Status:        result.StatusSent,
		CreatedAt:     time.Now().UTC(),
	}

	if obs.ValueQuantity != nil {
		entry.Value = obs.ValueQuantity.Value
		entry.Unit = obs.ValueQuantity.Unit
	}

	// Extract interpretation flag
	if len(obs.Interpretation) > 0 {
		ic := obs.Interpretation[0]
		entry.Flag = ic.Code
		if entry.Flag == "H" || entry.Flag == "L" {
			entry.HoldReason = fmt.Sprintf("Abnormal flag: %s", ic.Display)
			entry.Status = result.StatusHeld
		}
	}

	return entry
}

// deliverToLIS sends the result to the LIS via MLLP/HL7.
func (w *OutboundWorker) deliverToLIS(ctx context.Context, cr *domain.CanonicalResult) *domain.DeliveryStatus {
	adapter := outbound.NewHL7Adapter(outbound.HL7Config{
		Host:      w.cfg.DefaultLISHost,
		Port:      w.cfg.DefaultLISPort,
		TLS:       false,
		Timeout:   10 * time.Second,
		MaxRetries: 2,
		RetryBackoff: 1 * time.Second,
	})

	// If we have a diagnostic report, send it
	report, ok := cr.Observations.(*canonical.DiagnosticReport)
	if !ok {
		// Try to build from result entries if we have a store
		log.Printf("[Outbound] No diagnostic report available for delivery, skipping MLLP send")
		return &domain.DeliveryStatus{
			CorrelationID: cr.CorrelationID,
			Success:       true,
			DeliveredAt:   time.Now(),
		}
	}

	status, err := adapter.Send(ctx, report, cr.SampleID)

	// Update DB delivery status
	if w.resultStore != nil && err == nil {
		// Find all results for this correlation and mark as delivered
		results, _ := w.resultStore.List(result.ResultFilter{SampleID: cr.SampleID})
		for _, r := range results {
			if r.Status == result.StatusSent || r.Status == result.StatusApproved {
				ds := result.StatusDelivered
				if !status.Success {
					ds = result.StatusFailed
				}
				_ = w.resultStore.(*result.SQLiteStore).UpdateDeliveryStatus(r.ID, ds)
			}
		}
	}

	if err != nil {
		log.Printf("[Outbound] Delivery error for sample %s: %v", cr.SampleID, err)
	} else {
		log.Printf("[Outbound] Delivered to LIS (%s:%d) - Sample: %s, Success: %v",
			w.cfg.DefaultLISHost, w.cfg.DefaultLISPort, cr.SampleID, status.Success)
	}

	return status
}

