func (e *Extractor) ExtractFromASTM(msg *astm.Message) (*ExtractedData, error) {
	data := &ExtractedData{
		Extra: make(map[string]string),
	}

	ext := &e.profile.Extraction

	// Extract named fields
	if ext.SampleID != "" {
		data.SampleID = e.resolveASTMPath(msg, ext.SampleID, "1")
	}
