	}
	if ext.DateTime != "" {
		data.DateTime = e.resolveASTMPath(msg, ext.DateTime, "1")
	}
	if ext.InstrumentID != "" {
		data.InstrumentID = e.resolveASTMPath(msg, ext.InstrumentID, "1")
	}

	// Extract extra fields
	for name, path := range ext.Extra {
		data.Extra[name] = e.resolveASTMPath(msg, path, "1")
	}

	// For testCode and value with wildcard *, extract the first match
	if strings.Contains(ext.TestCode, "*") {
		data.TestCode = e.resolveASTMPath(msg, ext.TestCode, "1")
	}
	if strings.Contains(ext.Value, "*") {
		data.Value = e.resolveASTMPath(msg, ext.Value, "1")
	}

	return data, nil
}

