func (e *Extractor) ExtractFromHL7(msg *hl7.Message) (*ExtractedData, error) {
	data := &ExtractedData{
		Extra: make(map[string]string),
	}

	ext := &e.profile.Extraction

	if ext.SampleID != "" {
