// resolveASTMPath resolves a path expression against an ASTM message.
func (e *Extractor) resolveASTMPath(msg *astm.Message, path string, defaultSegIdx string) string {
	fp, err := ParsePath(path)
	if err != nil {
		return ""
	}

	segIdx := fp.SegmentIdx
	if segIdx == "" || segIdx == "*" {
		segIdx = defaultSegIdx
	}

